Sort of.   I posted the snippet in above answer. It looks like:
```
in processJobs():
for {

		// Iterate over the copy of the jobs map
	for jobid, proc := range pendingJobs {
		proc.status = pb.JobStatusResponse_RUNNING

		go func(jobid int64, proc *Process) {

                                //exec command
				cmd := exec.CommandContext(context.Background(), command)
				stdout, err := cmd.StdoutPipe()

				// Start the command
				err = cmd.Start()
				proc.startTime = time.Now()
				if err != nil {
					proc.status = pb.JobStatusResponse_FAILED
					return
				}
				proc.pid = cmd.Process.Pid

				// Read output from command stdout and save to byte array
				var output []byte
				buffer := make([]byte, bufferSize) // Define a buffer with a reasonable size

				reader := bufio.NewReader(stdout)
				for {

					// Read a chunk of data into the buffer
					n, err := reader.Read(buffer)
					if err != nil {
						if err == io.EOF {
							// EOF reached, break the loop
							break
						}
						// Handle other errors
						proc.status = pb.JobStatusResponse_FAILED
						proc.duration = time.Since(proc.startTime)
						return
					}

					// Append the read bytes from the buffer to the output slice
					output = append(output, buffer[:n]...)
					proc.output = output

				}
				proc.status = pb.JobStatusResponse_COMPLETED
				proc.output = output
			}(jobid, proc)
			````

